// Validate the actual extra-tube session operation on the deterministic corpus regenerated by audit-product-08.mjs.
import fs from 'node:fs';import {fresh,levels,levelKey,attempt,expanded,undone,restarted,validSave} from '../src/core/session.ts';import {solve} from '../src/core/solver.ts';import {apply,won} from '../src/core/rules.ts';
const out=process.env.UI_AUDIT_DIR??'test-results/project-10',rows=JSON.parse(fs.readFileSync(out+'/exploratory-corpus.json')),result={tested:0,validExpanded:0,found:0,validPaths:0,validUndoRestart:0};
for(const p of rows.filter(p=>p.status==='UNSOLVABLE')){
 const s=fresh();s.current=levels.findIndex(l=>l.id===p.level);s.attempts[levelKey(s.current)]={board:p.board,history:p.history,extra:false};const before=JSON.stringify(s),n=expanded(s);result.tested++;
 if(JSON.stringify(s)!==before||!validSave(n)||expanded(n)!==n)throw Error('expansion integrity');result.validExpanded++;
 if(!validSave(undone(n))||!validSave(restarted(n)))throw Error('undo/restart integrity');result.validUndoRestart++;
 const r=solve(attempt(n).board);if(r.status==='FOUND'){result.found++;let b=attempt(n).board;for(const m of r.path)b=apply(b,m);if(!won(b))throw Error('invalid path');result.validPaths++;}
}
fs.writeFileSync(out+'/actual-extra.json',JSON.stringify({...result,note:'Actual expanded/undone/restarted model functions, not ad integration or human success rates.'},null,2));console.log(JSON.stringify(result));
